script:
(function () {
  'use strict';
  // Bond price and yield to maturity, valued on a coupon date (no accrued interest).
  // With face F, annual coupon rate c, k payments a year, N = years x k payments and an annual
  // yield y compounded k times a year (j = y/k):
  //   price = (cF/k) x (1 - (1 + j)^-N) / j + F x (1 + j)^-N      (j = 0: cF/k x N + F)
  // Yield to maturity solves that equation for y by bisection (price falls as yield rises).
  // Macaulay duration = sum(t x PV of each payment) / price, in years; modified = Macaulay / (1 + j).
  // Verified (scratchpad tests/bd.test.js): face 100, 5% annual coupon, 6% yield, 3 years =
  // $97.3270; face 1,000, 5% semiannual, 6% yield, 10 years = $925.61; yield of a bond priced
  // at par = its coupon rate; 3-year 10% annual coupon at a 10% yield has a Macaulay duration of
  // 2.7355 years (textbook value, shown as 2.736); zero-coupon $1,000, 5 years at 4% annual = $821.93.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) { return (x * 100).toFixed(3) + '%'; }

  function price(face, coupon, k, n, y) {
    var c = face * coupon / k, j = y / k;
    if (Math.abs(j) < 1e-12) return c * n + face;
    var d = Math.pow(1 + j, -n);
    return c * (1 - d) / j + face * d;
  }

  function solveYield(face, coupon, k, n, target) {
    var lo = -0.5 * k, hi = 10 * k;
    if (target > price(face, coupon, k, n, lo) || target < price(face, coupon, k, n, hi)) return NaN;
    for (var i = 0; i < 200; i++) {
      var mid = (lo + hi) / 2;
      if (price(face, coupon, k, n, mid) > target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function cashFlows(face, coupon, k, n, y) {
    var c = face * coupon / k, j = y / k, rows = [], weighted = 0, total = 0;
    for (var t = 1; t <= n; t++) {
      var cf = c + (t === n ? face : 0), pv = cf / Math.pow(1 + j, t);
      weighted += (t / k) * pv;
      total += pv;
      rows.push({ period: t, years: t / k, cf: cf, pv: pv });
    }
    var mac = total > 0 ? weighted / total : 0;
    return { rows: rows, macaulay: mac, modified: mac / (1 + j) };
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(message) {
    var error = document.getElementById('bdError');
    error.hidden = false;
    error.textContent = message;
    ['bdMain', 'bdPer100', 'bdCurrent', 'bdCouponPay', 'bdStatus', 'bdMacaulay', 'bdModified'].forEach(function (id) { set(id, '–'); });
    document.getElementById('bdSchedule').innerHTML = '';
  }

  function update() {
    var mode = document.getElementById('bdMode').value;
    document.getElementById('bdYieldField').hidden = mode !== 'price';
    document.getElementById('bdPriceField').hidden = mode !== 'yield';

    var face = num('bdFace'), coupon = num('bdCoupon'), years = num('bdYears'),
        k = parseInt(document.getElementById('bdFreq').value, 10), y = num('bdYield'), p = num('bdPrice');
    var n = Math.round(years * k);
    var bad = [face, coupon, years, k].some(isNaN) || face <= 0 || coupon < 0 || coupon > 100 || years <= 0 || years > 100 || n < 1 ||
              (mode === 'price' && (isNaN(y) || y < -10 || y > 100)) ||
              (mode === 'yield' && (isNaN(p) || p <= 0));
    if (bad) {
      clear(mode === 'price'
        ? 'Enter a face value above $0, a coupon rate from 0 to 100%, a yield from -10 to 100% and a time to maturity of at least one payment period (up to 100 years).'
        : 'Enter a face value above $0, a coupon rate from 0 to 100%, a price above $0 and a time to maturity of at least one payment period (up to 100 years).');
      return;
    }
    coupon = coupon / 100;
    var bondPrice;
    if (mode === 'price') {
      y = y / 100;
      bondPrice = price(face, coupon, k, n, y);
      set('bdMainLabel', 'Bond price');
      set('bdMain', money.format(bondPrice));
    } else {
      bondPrice = p;
      y = solveYield(face, coupon, k, n, p);
      if (isNaN(y)) { clear('No realistic yield produces that price. Check the price and the face value.'); return; }
      set('bdMainLabel', 'Yield to maturity');
      set('bdMain', pct(y));
    }
    document.getElementById('bdError').hidden = true;
    var flows = cashFlows(face, coupon, k, n, y), annualCoupon = face * coupon;
    set('bdPer100', (bondPrice / face * 100).toFixed(3));
    set('bdCurrent', pct(annualCoupon / bondPrice));
    set('bdCouponPay', money.format(annualCoupon / k));
    var diff = bondPrice - face;
    set('bdStatus', Math.abs(diff) < 0.005 ? 'At par' : (diff > 0 ? 'Premium of ' + money.format(diff) : 'Discount of ' + money.format(-diff)));
    set('bdMacaulay', flows.macaulay.toFixed(3) + ' years');
    set('bdModified', flows.modified.toFixed(3));
    set('bdYearsNote', n + ' payments' + (Math.abs(n / k - years) > 1e-9 ? ' (maturity rounded to ' + (n / k).toFixed(2) + ' years)' : ''));
    document.getElementById('bdSchedule').innerHTML = flows.rows.map(function (row) {
      return '<tr><td>' + row.period + '</td><td>' + (Math.round(row.years * 100) / 100) + '</td><td>' +
             money.format(row.cf) + '</td><td>' + money.format(row.pv) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('bdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
